"""Produce deterministic three-way procurement matching reports."""

from __future__ import annotations

import argparse
import csv
from collections import defaultdict
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
import json
from pathlib import Path
import sys
import xml.etree.ElementTree as ET


ITEM_FIELDS = ("item_id", "description", "base_unit", "eaches_per_case")
PO_FIELDS = (
    "po_id", "line_id", "supplier_id", "item_id", "ordered_qty", "unit",
    "unit_price", "currency",
)
LINE_FIELDS = (
    "po_id", "line_id", "supplier_id", "item_id", "ordered_qty",
    "received_qty", "invoiced_qty", "po_unit_price", "invoice_unit_price",
    "quantity_variance", "price_variance", "quantity_pass", "price_pass",
    "credit_applied", "line_payable", "status",
)
EXCEPTION_FIELDS = (
    "po_id", "line_id", "reason", "quantity_variance", "price_variance",
)
CENT = Decimal("0.01")
ZERO = Decimal(0)


class InputError(ValueError):
    """Raised when an input document is malformed or internally inconsistent."""


def decimal_value(value: object, where: str) -> Decimal:
    if value is None or str(value).strip() == "":
        raise InputError(f"{where}: missing decimal value")
    try:
        result = Decimal(str(value).strip())
    except InvalidOperation as exc:
        raise InputError(f"{where}: invalid decimal {value!r}") from exc
    if not result.is_finite():
        raise InputError(f"{where}: decimal must be finite")
    return result


def required(mapping: dict[str, object], name: str, where: str) -> str:
    value = mapping.get(name)
    if value is None or str(value).strip() == "":
        raise InputError(f"{where}: missing {name}")
    return str(value).strip()


def read_csv(path: Path, expected: tuple[str, ...]) -> list[dict[str, str]]:
    try:
        with path.open("r", encoding="utf-8", newline="") as stream:
            reader = csv.DictReader(stream)
            if reader.fieldnames != list(expected):
                raise InputError(
                    f"{path}: expected header {','.join(expected)}; got "
                    f"{','.join(reader.fieldnames or [])}"
                )
            rows = list(reader)
    except OSError as exc:
        raise InputError(f"cannot read {path}: {exc}") from exc
    for number, row in enumerate(rows, 2):
        if None in row:
            raise InputError(f"{path}:{number}: too many columns")
    return rows


def load_items(path: Path) -> dict[str, Decimal]:
    items: dict[str, Decimal] = {}
    for number, row in enumerate(read_csv(path, ITEM_FIELDS), 2):
        where = f"{path}:{number}"
        item_id = required(row, "item_id", where)
        if item_id in items:
            raise InputError(f"{where}: duplicate item_id {item_id}")
        required(row, "description", where)
        if required(row, "base_unit", where) != "each":
            raise InputError(f"{where}: base_unit must be 'each'")
        factor = decimal_value(row.get("eaches_per_case"), f"{where} eaches_per_case")
        if factor <= 0:
            raise InputError(f"{where}: eaches_per_case must be greater than zero")
        items[item_id] = factor
    return items


def converted(quantity: Decimal, unit: str, factor: Decimal, where: str) -> Decimal:
    if unit == "each":
        return quantity
    if unit == "case":
        return quantity * factor
    raise InputError(f"{where}: unsupported unit {unit!r}")


def load_pos(path: Path, items: dict[str, Decimal]) -> dict[tuple[str, str], dict[str, object]]:
    pos: dict[tuple[str, str], dict[str, object]] = {}
    for number, row in enumerate(read_csv(path, PO_FIELDS), 2):
        where = f"{path}:{number}"
        po_id = required(row, "po_id", where)
        line_id = required(row, "line_id", where)
        key = (po_id, line_id)
        if key in pos:
            raise InputError(f"{where}: duplicate PO line {po_id}/{line_id}")
        item_id = required(row, "item_id", where)
        if item_id not in items:
            raise InputError(f"{where}: unknown item_id {item_id}")
        quantity = decimal_value(row.get("ordered_qty"), f"{where} ordered_qty")
        price = decimal_value(row.get("unit_price"), f"{where} unit_price")
        if quantity < 0 or price < 0:
            raise InputError(f"{where}: ordered quantity and unit price cannot be negative")
        unit = required(row, "unit", where)
        factor = items[item_id]
        normalized_quantity = converted(quantity, unit, factor, where)
        normalized_price = price / factor if unit == "case" else price
        pos[key] = {
            "po_id": po_id,
            "line_id": line_id,
            "supplier_id": required(row, "supplier_id", where),
            "item_id": item_id,
            "currency": required(row, "currency", where),
            "ordered_qty": normalized_quantity,
            "po_unit_price": normalized_price,
        }
    return pos


def validate_supplier_currencies(pos: dict[tuple[str, str], dict[str, object]]) -> dict[str, str]:
    currencies: dict[str, str] = {}
    po_headers: dict[str, tuple[str, str]] = {}
    for row in pos.values():
        supplier = str(row["supplier_id"])
        currency = str(row["currency"])
        if supplier in currencies and currencies[supplier] != currency:
            raise InputError(f"supplier {supplier} has multiple PO currencies")
        currencies[supplier] = currency
        po_id = str(row["po_id"])
        header = (supplier, currency)
        if po_id in po_headers and po_headers[po_id] != header:
            raise InputError(f"PO {po_id} has inconsistent supplier or currency")
        po_headers[po_id] = header
    return currencies


def load_receipts(path: Path, pos: dict[tuple[str, str], dict[str, object]], items: dict[str, Decimal]) -> dict[tuple[str, str], Decimal]:
    try:
        with path.open("r", encoding="utf-8") as stream:
            document = json.load(stream, parse_float=Decimal, parse_int=Decimal)
    except (OSError, json.JSONDecodeError) as exc:
        raise InputError(f"cannot read {path}: {exc}") from exc
    if not isinstance(document, dict) or not isinstance(document.get("receipts"), list):
        raise InputError(f"{path}: expected an object containing a receipts array")
    totals: dict[tuple[str, str], Decimal] = defaultdict(Decimal)
    receipt_ids: set[str] = set()
    for index, record in enumerate(document["receipts"], 1):
        where = f"{path}: receipt {index}"
        if not isinstance(record, dict):
            raise InputError(f"{where}: expected an object")
        po_id = required(record, "po_id", where)
        line_id = required(record, "line_id", where)
        key = (po_id, line_id)
        if key not in pos:
            raise InputError(f"{where}: unknown PO line {po_id}/{line_id}")
        receipt_id = required(record, "receipt_id", where)
        if receipt_id in receipt_ids:
            raise InputError(f"{where}: duplicate receipt_id {receipt_id}")
        receipt_ids.add(receipt_id)
        required(record, "received_date", where)
        quantity = decimal_value(record.get("quantity"), f"{where} quantity")
        if quantity < 0:
            raise InputError(f"{where}: quantity cannot be negative")
        unit = required(record, "unit", where)
        factor = items[str(pos[key]["item_id"])]
        totals[key] += converted(quantity, unit, factor, where)
    return totals


def load_invoices(path: Path, pos: dict[tuple[str, str], dict[str, object]], items: dict[str, Decimal]) -> tuple[dict[tuple[str, str], Decimal], dict[tuple[str, str], Decimal], dict[str, Decimal], dict[str, Decimal]]:
    try:
        root = ET.parse(path).getroot()
    except (OSError, ET.ParseError) as exc:
        raise InputError(f"cannot read {path}: {exc}") from exc
    if root.tag != "supplier_invoices":
        raise InputError(f"{path}: root element must be supplier_invoices")
    quantities: dict[tuple[str, str], Decimal] = defaultdict(Decimal)
    extensions: dict[tuple[str, str], Decimal] = defaultdict(Decimal)
    freight: dict[str, Decimal] = defaultdict(Decimal)
    tax: dict[str, Decimal] = defaultdict(Decimal)
    invoice_ids: set[str] = set()
    invoice_line_ids: set[str] = set()
    for index, invoice in enumerate(root, 1):
        where = f"{path}: invoice {index}"
        if invoice.tag != "invoice":
            raise InputError(f"{where}: unexpected element {invoice.tag}")
        invoice_id = required(invoice.attrib, "invoice_id", where)
        if invoice_id in invoice_ids:
            raise InputError(f"{where}: duplicate invoice_id {invoice_id}")
        invoice_ids.add(invoice_id)
        required(invoice.attrib, "invoice_date", where)
        po_id = required(invoice.attrib, "po_id", where)
        supplier = required(invoice.attrib, "supplier_id", where)
        currency = required(invoice.attrib, "currency", where)
        matching_po_lines = [row for key, row in pos.items() if key[0] == po_id]
        if not matching_po_lines:
            raise InputError(f"{where}: unknown po_id {po_id}")
        if any(row["supplier_id"] != supplier for row in matching_po_lines):
            raise InputError(f"{where}: supplier does not match PO {po_id}")
        if any(row["currency"] != currency for row in matching_po_lines):
            raise InputError(f"{where}: currency does not match PO {po_id}")
        invoice_freight = decimal_value(invoice.attrib.get("freight"), f"{where} freight")
        invoice_tax = decimal_value(invoice.attrib.get("tax"), f"{where} tax")
        if invoice_freight < 0 or invoice_tax < 0:
            raise InputError(f"{where}: freight and tax cannot be negative")
        freight[supplier] += invoice_freight
        tax[supplier] += invoice_tax
        for line_number, line in enumerate(invoice, 1):
            line_where = f"{where}, line {line_number}"
            if line.tag != "line":
                raise InputError(f"{line_where}: unexpected element {line.tag}")
            invoice_line_id = required(line.attrib, "invoice_line_id", line_where)
            if invoice_line_id in invoice_line_ids:
                raise InputError(f"{line_where}: duplicate invoice_line_id {invoice_line_id}")
            invoice_line_ids.add(invoice_line_id)
            po_line_id = required(line.attrib, "po_line_id", line_where)
            key = (po_id, po_line_id)
            if key not in pos:
                raise InputError(f"{line_where}: unknown PO line {po_id}/{po_line_id}")
            item_id = required(line.attrib, "item_id", line_where)
            if item_id not in items:
                raise InputError(f"{line_where}: unknown item_id {item_id}")
            if item_id != pos[key]["item_id"]:
                raise InputError(f"{line_where}: item does not match PO line {po_id}/{po_line_id}")
            quantity = decimal_value(line.attrib.get("quantity"), f"{line_where} quantity")
            unit_price = decimal_value(line.attrib.get("unit_price"), f"{line_where} unit_price")
            if quantity < 0 or unit_price < 0:
                raise InputError(f"{line_where}: quantity and unit price cannot be negative")
            unit = required(line.attrib, "unit", line_where)
            quantities[key] += converted(quantity, unit, items[item_id], line_where)
            extensions[key] += quantity * unit_price
    return quantities, extensions, freight, tax


def money(value: Decimal) -> str:
    return format(value.quantize(CENT, rounding=ROUND_HALF_UP), ".2f")


def quantity(value: Decimal) -> str:
    if value == 0:
        return "0"
    displayed = format(value, "f")
    return displayed.rstrip("0").rstrip(".") if "." in displayed else displayed


def write_csv(path: Path, fields: tuple[str, ...], rows: list[dict[str, str]]) -> None:
    with path.open("w", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=fields, lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def create_reports(input_dir: Path, output_dir: Path) -> None:
    items = load_items(input_dir / "items.csv")
    pos = load_pos(input_dir / "purchase_orders.csv", items)
    supplier_currencies = validate_supplier_currencies(pos)
    receipts = load_receipts(input_dir / "goods_receipts.json", pos, items)
    invoice_qty, extensions, freight, tax = load_invoices(
        input_dir / "supplier_invoices.xml", pos, items
    )

    line_rows: list[dict[str, str]] = []
    exception_rows: list[dict[str, str]] = []
    line_gross: dict[str, Decimal] = defaultdict(Decimal)
    line_payable: dict[str, Decimal] = defaultdict(Decimal)
    for key in sorted(pos):
        po = pos[key]
        ordered = po["ordered_qty"]
        received = receipts[key]
        invoiced = invoice_qty[key]
        extension = extensions[key]
        invoice_price = extension / invoiced if invoiced != 0 else ZERO
        po_price = po["po_unit_price"]
        quantity_variance = abs(received - invoiced)
        price_variance = abs(invoice_price - po_price)
        quantity_pass = quantity_variance <= Decimal("0.02") * ordered
        price_pass = price_variance <= Decimal("0.01") * po_price
        supplier = str(po["supplier_id"])
        displayed_payable = extension.quantize(CENT, rounding=ROUND_HALF_UP)
        displayed_gross = extension.quantize(CENT, rounding=ROUND_HALF_UP)
        line_gross[supplier] += displayed_gross
        line_payable[supplier] += displayed_payable
        row = {
            "po_id": key[0], "line_id": key[1], "supplier_id": supplier,
            "item_id": str(po["item_id"]), "ordered_qty": quantity(ordered),
            "received_qty": quantity(received), "invoiced_qty": quantity(invoiced),
            "po_unit_price": money(po_price), "invoice_unit_price": money(invoice_price),
            "quantity_variance": quantity(quantity_variance),
            "price_variance": money(price_variance),
            "quantity_pass": str(quantity_pass).lower(),
            "price_pass": str(price_pass).lower(), "credit_applied": "0.00",
            "line_payable": money(displayed_payable),
            "status": "pass" if quantity_pass and price_pass else "exception",
        }
        line_rows.append(row)
        if not quantity_pass:
            exception_rows.append({
                "po_id": key[0], "line_id": key[1], "reason": "quantity",
                "quantity_variance": row["quantity_variance"],
                "price_variance": row["price_variance"],
            })
        if not price_pass:
            exception_rows.append({
                "po_id": key[0], "line_id": key[1], "reason": "price",
                "quantity_variance": row["quantity_variance"],
                "price_variance": row["price_variance"],
            })
    exception_rows.sort(key=lambda row: (row["po_id"], row["line_id"], row["reason"]))

    suppliers = []
    for supplier in sorted(supplier_currencies):
        supplier_freight = freight[supplier].quantize(CENT, rounding=ROUND_HALF_UP)
        supplier_tax = tax[supplier].quantize(CENT, rounding=ROUND_HALF_UP)
        payable = line_payable[supplier]
        suppliers.append({
            "supplier_id": supplier,
            "currency": supplier_currencies[supplier],
            "line_gross": money(line_gross[supplier]),
            "credit_applied": "0.00",
            "line_payable": money(payable),
            "freight": money(supplier_freight),
            "tax": money(supplier_tax),
            "header_credit": "0.00",
            "unapplied_credit": "0.00",
            "final_payable": money(payable + supplier_freight + supplier_tax),
        })

    try:
        output_dir.mkdir(parents=True, exist_ok=True)
        if not output_dir.is_dir():
            raise InputError(f"output path is not a directory: {output_dir}")
        write_csv(output_dir / "line_matches.csv", LINE_FIELDS, line_rows)
        write_csv(output_dir / "exceptions.csv", EXCEPTION_FIELDS, exception_rows)
        with (output_dir / "supplier_summary.json").open("w", encoding="utf-8", newline="\n") as stream:
            json.dump({"suppliers": suppliers}, stream, indent=2)
            stream.write("\n")
    except OSError as exc:
        raise InputError(f"cannot write output directory {output_dir}: {exc}") from exc


def parse_args(argv: list[str] | None = None) -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("input_dir", type=Path)
    parser.add_argument("--output", required=True, type=Path, dest="output_dir")
    return parser.parse_args(argv)


def main(argv: list[str] | None = None) -> int:
    args = parse_args(argv)
    try:
        create_reports(args.input_dir, args.output_dir)
    except InputError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
